// Separately authored adapter around the pinned native animation APIs.
#include "actor_descriptors.hpp"
#include "assets.hpp"
#include <iostream>
int main(int argc,char**argv){try{if(argc!=2)return 2;rr::Assets a(argv[1]);rr::ActorAnimationLibrary l(a.read("ROADRASH.EXE"),a.read("DATA/GLOBAL.RSC"));bool first=true;std::cout<<"[";for(int bank=0;bank<2;++bank)for(int code=0;code<52;++code){if(!l.playback[bank][code])continue;rr::ActorAnimationState s;rr::set_animation(s,l.playback[bank],int8_t(code),0);for(uint32_t tick=0;tick<180;++tick){auto*f=rr::advance_animation(s,l.playback[bank],tick);if(!f)break;auto v=rr::select_actor_view(*f,l.views[bank],0,0);auto c=l.views[bank][v.group][v.subframe];if(!first){std::cout<<",";}first=false;std::cout<<"["<<bank<<","<<code<<","<<tick<<","<<int(s.animation)<<","<<int(s.frame)<<","<<int(s.loops)<<","<<s.deadline<<",[";for(int i=0;i<12;++i){if(i)std::cout<<",";std::cout<<int(f->render[i]);}std::cout<<"],"<<int(f->duration)<<","<<int(f->control)<<","<<f->flags<<","<<c.frame<<","<<c.flags<<",[";bool fa=true;for(int yaw:{-0x100000,0,0x100000})for(int roll:{-0x200000,0,0x200000}){auto v2=rr::select_actor_view(*f,l.views[bank],yaw,roll);auto c2=l.views[bank][v2.group][v2.subframe];if(!fa){std::cout<<",";}fa=false;std::cout<<"["<<c2.frame<<","<<c2.flags<<","<<v2.roll<<"]";}std::cout<<"]]";}}std::cout<<"]\n";}catch(std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
